// Facet Fauna: Dogs - mix-and-match kit for three.js.
//
// Assembles a dog from the kit's parts (a build with its skeleton and clips, a
// head with its hinged jaw, a pair of ears, a tail and a coat shell) and colours
// it with pattern masks, so any combination - and any cross of two dogs - can be
// made at run time. For a fixed dog with no code, load a ready-made breed from
// breeds/ instead.
//
//   import { loadDogKit } from './dogkit.js';
//   const kit = await loadDogKit('assets/dogs/kit/');          // the folder holding the dog_*.glb parts
//   const dog = kit.makeDog('Beagle');                         // a breed from the table below ...
//   const pup = kit.makeDog(kit.breed('Pug', 'Beagle'));       // ... or a cross of two
//   scene.add(dog.object);
//   dog.play('trot');
//   // every frame:  dog.update(dt);
//
// A dog is described by the same fields as a breed (names from the catalog):
// build, size (XS-XL), head ('classic' = the build's own head, or fox / wedge /
// flat), ears, tail, coat (smooth, wire, ruff, puff, feathered, curly, shaggy,
// long, corded, poodleclip, hairless), base (colour), layers ("pattern:colour|..."
// up to three, painted in order), nose; and optionally wear: ['collar'] or
// ['bandana']. Dogs are lit by the scene's lights (a standard material with the
// pattern colours drawn in its shader).
import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import * as SkeletonUtils from 'three/addons/utils/SkeletonUtils.js';
import { MeshoptDecoder } from 'three/addons/libs/meshopt_decoder.module.js';

// Where the parts live under `base`. 'pack': the asset library's flat kit
// folder (the default). 'source': run-dog-pack/kit in run-workshop.
const LAYOUTS = {
  pack: { build: b => `dog_build_${b}.glb`, head: h => `dog_head_${h}.glb`, ear: (e, s) => `dog_ear_${e}_${s}.glb`,
          tail: t => `dog_tail_${t}.glb`, wear: b => `dog_wear_${b}.glb`,
          pattern: (kind, key) => `patterns/dog_pattern_${kind}_${key}.png` },
  source: { build: b => `builds/${b}.glb`, head: h => `heads/${h}.glb`, ear: (e, s) => `parts/ear-${e}-${s}.glb`,
            tail: t => `parts/tail-${t}.glb`, wear: b => `wearables/${b}.glb`,
            pattern: (kind, key) => `patterns/${kind}-${key}.png` },
};

