// The kit's papercraft palette: coat colours lifted toward soft pastels
// (lighter, less saturated), darks kept deep. Noses are left as they are.
function papercraft(hex) {
  const c = new THREE.Color(hex), hsl = {};
  c.getHSL(hsl);
  const lift = 0.22 * THREE.MathUtils.smoothstep(hsl.l, 0.15, 0.55);
  c.setHSL(hsl.h, hsl.s * (1 - 0.28 * lift / 0.22), hsl.l + (1 - hsl.l) * lift);
  return c;
}

// Standard material + the kit's colouring: base coat, three pattern layers
// (region masks read through the anatomical UV set, tile masks through UV0),
// tagged faces (COLOR_0: red = nose, green = eyes) and, on the head and jaw,
// back faces in the mouth colour (the inside of the mouth).
function coatMaterial(shared, { part = false, partUv = [0, 0], uvScale = 1, mouth = false } = {}) {
  const m = new THREE.MeshStandardMaterial({ roughness: 1, metalness: 0, flatShading: true,
                                             side: mouth ? THREE.DoubleSide : THREE.FrontSide });
  const own = { isPart: { value: part ? 1 : 0 }, partUv: { value: new THREE.Vector2(...partUv) },
                uvScale: { value: uvScale } };
  m.onBeforeCompile = sh => {
    Object.assign(sh.uniforms, shared, own);
    sh.vertexShader = sh.vertexShader
      .replace('#include <common>', `#include <common>
        attribute vec4 color;
        attribute vec2 uv1;
        uniform float uvScale;
        varying vec2 vKitUv; varying vec2 vKitUv1; varying vec2 vKitTag;`)
      .replace('#include <begin_vertex>', `#include <begin_vertex>
        vKitUv = uv * uvScale; vKitUv1 = uv1; vKitTag = color.rg;`);
    sh.fragmentShader = sh.fragmentShader
      .replace('#include <common>', `#include <common>
        uniform vec3 coat, color1, color2, color3, noseColor, eyeColor, mouthColor;
        uniform sampler2D tex1, tex2, tex3;
        uniform float mode1, mode2, mode3, isPart;
        uniform vec2 partUv;
        varying vec2 vKitUv; varying vec2 vKitUv1; varying vec2 vKitTag;
        float kitLayer(sampler2D tex, float mode) {
          if (mode < 0.5) return 0.0;
          float t = texture2D(tex, mode < 1.5 ? mix(vKitUv1, partUv, isPart) : vKitUv).r;
          float aa = fwidth(t);
          return smoothstep(0.5 - aa, 0.5 + aa, t);
        }`)
      .replace('vec4 diffuseColor = vec4( diffuse, opacity );', `
        vec3 c = coat;
        c = mix(c, color1, kitLayer(tex1, mode1));
        c = mix(c, color2, kitLayer(tex2, mode2));
        c = mix(c, color3, kitLayer(tex3, mode3));
        c = mix(c, noseColor, step(0.5, vKitTag.r));
        c = mix(c, eyeColor, step(0.5, vKitTag.g) * (1.0 - step(0.5, vKitTag.r)));
        ${mouth ? 'if (!gl_FrontFacing) c = mouthColor;' : ''}
        vec4 diffuseColor = vec4(c, opacity);`);
  };
  return m;
}

export async function loadDogKit(base = './', { layout = 'pack', palette = 'papercraft' } = {}) {
  if (!base.endsWith('/')) base += '/';
  const L = LAYOUTS[layout];
  const gltf = new GLTFLoader().setMeshoptDecoder(MeshoptDecoder);
  const catalog = DATA.catalog;
  const breeds = Object.fromEntries(DATA.breeds.map(r => [r.breed, r]));
  const byName = (g, n) => g.scene.getObjectByName(n);
  const sanitize = THREE.PropertyBinding.sanitizeNodeName;

  // Parts load on first use, so a game that only makes beagles only loads the
  // scenthound build. Call kit.preload(...) to load ahead (e.g. on a loading screen).
  const cache = {};
  const get = (key, url, make) => (cache[key] ||= gltf.loadAsync(base + url).then(make));
  const build = b => get(`b:${b}`, L.build(b), g => ({ scene: g.scene, clips: g.animations,
    looping: byName(g, 'rig')?.userData.looping_clips || [] }));
  const head = h => get(`h:${h}`, L.head(h), g => {
    const sockets = {};
    g.scene.traverse(o => { if (o.name.startsWith('socket_')) sockets[o.name.slice(7)] = o; });
    const jaw = byName(g, 'jaw');
    return { head: byName(g, 'head').geometry, jaw: jaw.geometry, hinge: jaw.position.clone(), sockets,
             coats: Object.fromEntries(catalog.furs.map(f => [f, byName(g, `coat_${f}`)?.geometry])) };
  });
  const ear = (e, s) => get(`e:${e}-${s}`, L.ear(e, s), g => byName(g, `ear-${e}-${s}`).geometry);
  const tail = t => get(`t:${t}`, L.tail(t), g => byName(g, `tail-${t}`).geometry);
  const wear = b => get(`w:${b}`, L.wear(b), g => g.scene);
  const texLoader = new THREE.TextureLoader();
  const masks = {};
  await Promise.all(Object.entries(catalog.patterns).map(async ([name, p]) => {
    const t = await texLoader.loadAsync(base + L.pattern(p.region ? 'region' : 'tile', p.region || p.tile));
    if (p.region) t.flipY = false;          // read through the glTF UV set: glTF convention
    else t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.needsUpdate = true;
    masks[name] = { tex: t, mode: p.region ? 1 : 2 };
  }));
  const blank = new THREE.DataTexture(new Uint8Array([0, 0, 0, 255]), 1, 1);
  blank.needsUpdate = true;
  const coatColour = name => (palette === 'papercraft' ? papercraft : c => new THREE.Color(c))(catalog.colours[name] || '#999999');

  const describe = spec => {
    const r = typeof spec === 'string' ? breeds[spec] : spec;
    if (!r) throw new Error(`No breed "${spec}"`);
    const h = r.head || catalog.headForBuild[r.build] || 'classic';
    return { r, headFile: h === 'classic' ? `classic-${r.build}` : h, fur: catalog.coatShell[r.coat] || 'none' };
  };

  // Load every part a dog (or list of dogs) needs.
  async function preload(...specs) {
    await Promise.all(specs.flatMap(s => {
      const { r, headFile } = describe(s);
      return [build(r.build), head(headFile), ear(r.ears, 'L'), ear(r.ears, 'R'), tail(r.tail),
              ...(r.wear?.length ? [wear(r.build)] : [])];
    }));
  }

  // A dog. Async because its parts may still need loading; preload() first and
  // it resolves at once.
  async function makeDog(spec) {
    const { r, headFile, fur } = describe(spec);
    await preload(r);
    const [B, H, earL, earR, T] = await Promise.all([build(r.build), head(headFile), ear(r.ears, 'L'), ear(r.ears, 'R'), tail(r.tail)]);

    const shared = { coat: { value: new THREE.Color() }, noseColor: { value: new THREE.Color() },
                     eyeColor: { value: new THREE.Color(catalog.fixedColours.eye) },
                     mouthColor: { value: new THREE.Color(catalog.fixedColours.mouth) } };
    [1, 2, 3].forEach(i => {
      shared[`color${i}`] = { value: new THREE.Color() };
      shared[`tex${i}`] = { value: blank };
      shared[`mode${i}`] = { value: 0 };
    });
    // Coat colours: base, up to three pattern layers ("pattern:colour|..."), nose.
    function recolour({ base: b = r.base, layers = r.layers, nose = r.nose } = {}) {
      shared.coat.value.copy(coatColour(b));
      shared.noseColor.value.set(catalog.noseColours[nose] || catalog.colours[nose] || catalog.noseColours.black);
      const ls = (layers || '').split('|').filter(Boolean).map(l => l.split(':'));
      [1, 2, 3].forEach(i => {
        const [pat, col] = ls[i - 1] || [];
        shared[`color${i}`].value.copy(col ? coatColour(col) : new THREE.Color('#ffffff'));
        shared[`tex${i}`].value = masks[pat]?.tex || blank;
        shared[`mode${i}`].value = masks[pat]?.mode || 0;
      });
    }
    recolour();

    // Body: the build's rig, with only this dog's coat shell shown.
    const rig = SkeletonUtils.clone(B.scene);
    const bodyMat = coatMaterial(shared);
    const sockets = {};
    let body;
    rig.traverse(o => {
      if (o.name.startsWith('socket_')) sockets[o.name.slice(7)] = o;
      if (!o.isMesh) return;
      o.material = bodyMat;
      o.frustumCulled = false;
      if (o.name === 'dog') body = o;
      if (o.name.startsWith('coat_')) o.visible = o.name === `coat_${fur}`;
    });

    // Tail on the tail socket, head group on the head socket: head, jaw (on its
    // hinge), head fluff, ears; and empties for the mouth and nose.
    const st = sockets.tail;
    const tailMesh = new THREE.Mesh(T, coatMaterial(shared, { part: true, partUv: st.userData.uv2, uvScale: st.scale.x }));
    st.add(tailMesh);
    const sh = sockets.head, headScale = sh.scale.x, earScale = sh.userData.ear_scale ?? 1;
    const group = new THREE.Group();
    group.add(new THREE.Mesh(H.head, coatMaterial(shared, { uvScale: headScale, mouth: true })));
    const jaw = new THREE.Mesh(H.jaw, coatMaterial(shared, { uvScale: headScale, mouth: true }));
    jaw.position.copy(H.hinge);
    group.add(jaw);
    if (fur !== 'none' && H.coats[fur]) group.add(new THREE.Mesh(H.coats[fur], coatMaterial(shared, { uvScale: headScale })));
    for (const [s, geo] of [['L', earL], ['R', earR]]) {
      const so = H.sockets[`ear_${s}`];
      const m = new THREE.Mesh(geo, coatMaterial(shared, { part: true, partUv: so.userData.uv2,
                                                            uvScale: headScale * so.scale.x * earScale }));
      m.position.copy(so.position);
      m.scale.copy(so.scale).multiplyScalar(earScale);
      group.add(m);
    }
    const mouth = new THREE.Object3D(), nose = new THREE.Object3D();
    mouth.position.copy(H.sockets.mouth.position);
    nose.position.copy(H.sockets.nose.position);
    group.add(mouth, nose);
    group.traverse(o => { if (o.isMesh) o.frustumCulled = false; });
    sh.add(group);

    // Collar or bandana: skinned to the dog's own skeleton (refit over coat shells).
    if (r.wear?.length) {
      const src = await wear(r.build);
      for (const item of r.wear) {
        const name = src.getObjectByName(`${item}@${fur}`) ? `${item}@${fur}` : item;
        src.getObjectByName(name)?.traverse(o => {
          if (!o.isSkinnedMesh) return;
          const map = o.skeleton.bones.map(b => body.skeleton.bones.findIndex(x => x.name === b.name));
          const geo = o.geometry.clone(), si = geo.attributes.skinIndex;
          for (let i = 0; i < si.count; i++) for (let c = 0; c < 4; c++) si.setComponent(i, c, Math.max(0, map[si.getComponent(i, c)]));
          const m = new THREE.SkinnedMesh(geo, o.material);
          m.frustumCulled = false;
          body.parent.add(m);
          m.bind(body.skeleton, body.bindMatrix);
        });
      }
    }

    // The jaw bone drives the jaw part; the grip bone's scale says whether the
    // mouth is holding something (1) or has let go (0).
    const jawBone = rig.getObjectByName('jaw'), jawRest = jawBone.quaternion.clone();
    const grip = rig.getObjectByName('grip');
    const q = new THREE.Quaternion();
    function follow() {
      q.copy(jawRest).invert().multiply(jawBone.quaternion);
      jaw.rotation.z = 2 * Math.atan2(q.x + q.y + q.z, q.w);
    }

    const length = catalog.sizes[r.size] * (catalog.buildLength[r.build] || 1);
    const object = new THREE.Group();
    object.add(rig);
    object.scale.setScalar(length);          // the kit is built 1 unit long: metres
    object.userData.dog = r;
    const mixer = new THREE.AnimationMixer(rig);
    let current = null;
    return {
      object, spec: r, length, mixer, clips: B.clips.map(c => c.name), looping: B.looping,
      clip: name => B.clips.find(c => c.name === name),
      mouth, nose,                              // add a toy to `mouth`, a treat to `nose`
      holding: () => grip.scale.x > 0.5,        // during pick_up, drop_it, toss, catch...
      recolour,                                 // any of { base, layers, nose } (catalog names)
      play(name, { fade = 0.15 } = {}) {
        const clip = B.clips.find(c => c.name === name);
        if (!clip) throw new Error(`No clip "${name}"`);
        const next = mixer.clipAction(clip);
        next.reset();
        next.setLoop(B.looping.includes(name) ? THREE.LoopRepeat : THREE.LoopOnce, Infinity);
        next.clampWhenFinished = true;
        next.play();
        if (current && current !== next && fade > 0) current.crossFadeTo(next, fade, false);
        else if (current && current !== next) current.stop();
        current = next;
        return next;
      },
      update(dt) { mixer.update(dt); follow(); },
    };
  }

  // A cross of two dogs: each field from one parent or the other.
  function breed(a, b, random = Math.random) {
    const pa = describe(a).r, pb = describe(b).r;
    const out = {};
    for (const k of ['build', 'size', 'head', 'ears', 'tail', 'coat', 'base', 'layers', 'nose'])
      out[k] = (random() < 0.5 ? pa : pb)[k];
    out.breed = `${pa.breed} × ${pb.breed}`;
    return out;
  }

  return { catalog, breeds, makeDog, breed, preload, recolourable: Object.keys(catalog.colours) };
}
